INSERT INTO exploration_event_templates (template_id, type, title, description, choices) VALUES
('event-001', 'trap', '流沙陷阱', '脚下的地面突然塌陷，露出深不见底的流沙坑。沙石不断往下倾泻，你必须迅速做出决定！', '[{"id":"event-001-choice-1","text":"快速跳跃越过流沙","requiredSkill":{"profession":"explorer","minLevel":3},"successRate":0.8,"effects":{"progressChange":5,"luckChange":1}},{"id":"event-001-choice-2","text":"寻找稳固的支点绕行","successRate":0.6,"effects":{"progressChange":-5}},{"id":"event-001-choice-3","text":"冒险直接冲过去","successRate":0.3,"effects":{"progressChange":10,"damage":true,"goldChange":-50}}]'::jsonb),
('event-002', 'collapse', '通道塌方', '头顶传来令人不安的碎裂声，支撑结构开始松动，石块正在不断掉落！', '[{"id":"event-002-choice-1","text":"工程师紧急加固通道","requiredSkill":{"profession":"engineer","minLevel":2},"successRate":0.85,"effects":{"progressChange":8,"luckChange":2}},{"id":"event-002-choice-2","text":"匍匐前进快速通过","successRate":0.5,"effects":{"progressChange":3,"damage":true}},{"id":"event-002-choice-3","text":"后退寻找其他通路","successRate":0.9,"effects":{"progressChange":-10}}]'::jsonb),
('event-003', 'rival', '敌对探险队', '前方出现了另一支探险队，他们看起来不怀好意，似乎想阻止你们继续前进。', '[{"id":"event-003-choice-1","text":"用金币买通他们让路","successRate":0.95,"effects":{"goldChange":-200,"progressChange":5}},{"id":"event-003-choice-2","text":"与他们正面交涉","requiredSkill":{"profession":"historian","minLevel":3},"successRate":0.65,"effects":{"progressChange":10,"luckChange":2,"goldChange":100}},{"id":"event-003-choice-3","text":"趁夜潜行避开他们","successRate":0.55,"effects":{"progressChange":-5,"luckChange":-1}}]'::jsonb),
('event-004', 'treasure', '隐藏宝箱', '在墙壁的缝隙中，你发现了一个古旧的木箱，上面的锁已经生锈，但看起来里面可能有好东西。', '[{"id":"event-004-choice-1","text":"用专业工具小心撬开","requiredSkill":{"profession":"engineer","minLevel":2},"successRate":0.9,"effects":{"goldChange":300,"findRelic":true,"progressChange":5}},{"id":"event-004-choice-2","text":"直接砸开箱子","successRate":0.7,"effects":{"goldChange":150,"findRelic":false,"progressChange":2}},{"id":"event-004-choice-3","text":"先研究上面的铭文","requiredSkill":{"profession":"linguist","minLevel":2},"successRate":0.8,"effects":{"goldChange":400,"findRelic":true,"progressChange":10}}]'::jsonb),
('event-005', 'discovery', '神秘壁画', '墙上描绘着精美的古代壁画，似乎在讲述一个被遗忘的故事，也许能揭示宝藏的位置。', '[{"id":"event-005-choice-1","text":"历史学家仔细解读壁画","requiredSkill":{"profession":"historian","minLevel":3},"successRate":0.85,"effects":{"progressChange":20,"luckChange":3,"goldChange":50}},{"id":"event-005-choice-2","text":"语言学家破译上面的文字","requiredSkill":{"profession":"linguist","minLevel":2},"successRate":0.75,"effects":{"progressChange":15,"findRelic":true}},{"id":"event-005-choice-3","text":"拍照存档继续前进","successRate":1.0,"effects":{"progressChange":3}}]'::jsonb),
('event-006', 'trap', '毒箭机关', '当你踏入一个看似普通的房间时，墙壁上突然出现了一排小孔，隐约能看到里面闪着寒光的箭头！', '[{"id":"event-006-choice-1","text":"工程师快速破解机关","requiredSkill":{"profession":"engineer","minLevel":3},"successRate":0.88,"effects":{"progressChange":10,"luckChange":2}},{"id":"event-006-choice-2","text":"探险家敏捷翻滚躲避","requiredSkill":{"profession":"explorer","minLevel":2},"successRate":0.7,"effects":{"progressChange":5,"damage":true}},{"id":"event-006-choice-3","text":"用盾牌硬挡过去","successRate":0.4,"effects":{"progressChange":-5,"damage":true,"goldChange":-100}}]'::jsonb),
('event-007', 'collapse', '水脉爆发', '挖掘时意外凿穿了一条地下水脉，冰冷的河水正在快速涌入通道！', '[{"id":"event-007-choice-1","text":"用石块快速封堵水源","requiredSkill":{"profession":"engineer","minLevel":2},"successRate":0.8,"effects":{"progressChange":5,"luckChange":1}},{"id":"event-007-choice-2","text":"游泳通过被淹通道","successRate":0.45,"effects":{"progressChange":15,"damage":true,"luckChange":-2}},{"id":"event-007-choice-3","text":"向高处撤退","successRate":0.95,"effects":{"progressChange":-15}}]'::jsonb),
('event-008', 'treasure', '祭坛贡品', '一座古老的祭坛上摆放着几件看起来很值钱的祭品，但祭坛周围似乎有某种禁忌的力量在守护。', '[{"id":"event-008-choice-1","text":"考古学家用专业方法取走","requiredSkill":{"profession":"archaeologist","minLevel":3},"successRate":0.85,"effects":{"findRelic":true,"goldChange":200,"progressChange":10}},{"id":"event-008-choice-2","text":"历史学家先研究祭祀仪式","requiredSkill":{"profession":"historian","minLevel":2},"successRate":0.75,"effects":{"findRelic":true,"goldChange":350,"luckChange":3}},{"id":"event-008-choice-3","text":"直接拿走最快的方式","successRate":0.35,"effects":{"findRelic":false,"goldChange":80,"damage":true,"luckChange":-3}}]'::jsonb),
('event-009', 'discovery', '古老图书馆', '你们发现了一间被遗忘的密室，里面堆满了年代久远的卷轴和典籍。灰尘覆盖的书架上可能隐藏着重要信息。', '[{"id":"event-009-choice-1","text":"语言学家系统整理典籍","requiredSkill":{"profession":"linguist","minLevel":3},"successRate":0.9,"effects":{"progressChange":25,"findRelic":true,"luckChange":2}},{"id":"event-009-choice-2","text":"快速翻阅寻找关键信息","successRate":0.55,"effects":{"progressChange":12,"goldChange":100}},{"id":"event-009-choice-3","text":"带走有价值的卷轴","requiredSkill":{"profession":"archaeologist","minLevel":2},"successRate":0.7,"effects":{"findRelic":true,"progressChange":5}}]'::jsonb),
('event-010', 'rival', '文物走私犯', '一伙武装走私犯出现在你们前方，他们也在寻找同样的宝藏，看起来不想和你们分享。', '[{"id":"event-010-choice-1","text":"假装合作设下圈套","requiredSkill":{"profession":"explorer","minLevel":4},"successRate":0.75,"effects":{"progressChange":15,"goldChange":500,"luckChange":2}},{"id":"event-010-choice-2","text":"贿赂他们分一杯羹","successRate":0.85,"effects":{"goldChange":-400,"progressChange":10}},{"id":"event-010-choice-3","text":"悄悄绕路避开他们","successRate":0.5,"effects":{"progressChange":-10,"luckChange":-1}}]'::jsonb),
('event-011', 'trap', '水银密室', '石门在身后关闭，房间地面开始缓缓流出银色的液态金属——是水银！吸入蒸气会是致命的！', '[{"id":"event-011-choice-1","text":"工程师紧急启动排水机关","requiredSkill":{"profession":"engineer","minLevel":4},"successRate":0.8,"effects":{"progressChange":20,"findRelic":true,"luckChange":3}},{"id":"event-011-choice-2","text":"屏住呼吸快速寻找出口","requiredSkill":{"profession":"explorer","minLevel":3},"successRate":0.55,"effects":{"progressChange":10,"damage":true}},{"id":"event-011-choice-3","text":"用衣物掩住口鼻撤退","successRate":0.9,"effects":{"progressChange":-20,"damage":false}}]'::jsonb),
('event-012', 'discovery', '地下墓室入口', '考古学家在清理浮土时发现了一个隐藏的石门，门上刻着守护符文，里面可能是某位重要人物的墓室。', '[{"id":"event-012-choice-1","text":"语言学家先破译符文","requiredSkill":{"profession":"linguist","minLevel":3},"successRate":0.8,"effects":{"progressChange":15,"findRelic":true,"luckChange":2}},{"id":"event-012-choice-2","text":"考古学家小心发掘入口","requiredSkill":{"profession":"archaeologist","minLevel":2},"successRate":0.75,"effects":{"progressChange":10,"findRelic":true}},{"id":"event-012-choice-3","text":"直接炸开石门","successRate":0.4,"effects":{"progressChange":5,"damage":true,"goldChange":-150}}]'::jsonb),
('event-013', 'treasure', '暗格藏金', '考古学家在清理地面时注意到一块地砖的颜色与众不同，敲击似乎是空的，下面可能藏着什么。', '[{"id":"event-013-choice-1","text":"小心撬开地砖查看","requiredSkill":{"profession":"archaeologist","minLevel":2},"successRate":0.85,"effects":{"goldChange":250,"findRelic":true,"progressChange":8}},{"id":"event-013-choice-2","text":"用探测器扫描内部","successRate":0.7,"effects":{"goldChange":180,"progressChange":5}},{"id":"event-013-choice-3","text":"不管它继续探索","successRate":1.0,"effects":{"progressChange":2}}]'::jsonb),
('event-014', 'collapse', '落石阻路', '前方发生了小规模塌方，大块岩石完全堵住了前进的道路，必须想办法清理。', '[{"id":"event-014-choice-1","text":"工程师用工具开路","requiredSkill":{"profession":"engineer","minLevel":2},"successRate":0.9,"effects":{"progressChange":12,"luckChange":1}},{"id":"event-014-choice-2","text":"众人合力搬开石块","successRate":0.5,"effects":{"progressChange":5,"damage":true}},{"id":"event-014-choice-3","text":"寻找其他路线","successRate":0.8,"effects":{"progressChange":-8}}]'::jsonb),
('event-015', 'rival', '古墓守卫', '一支神秘的守墓人出现在你们面前，他们世代守护着这座古墓，绝不允许外人亵渎。', '[{"id":"event-015-choice-1","text":"历史学家说明考古来意","requiredSkill":{"profession":"historian","minLevel":4},"successRate":0.7,"effects":{"progressChange":20,"findRelic":true,"luckChange":5}},{"id":"event-015-choice-2","text":"放下所有武器表示诚意","successRate":0.55,"effects":{"progressChange":10,"goldChange":-100}},{"id":"event-015-choice-3","text":"趁其不备快速通过","successRate":0.3,"effects":{"progressChange":5,"damage":true,"luckChange":-5}}]'::jsonb);
INSERT INTO players (id, username, email, password_hash, avatar, level, exp, gold, gems, total_relic_value, museum_score, is_committee)
INSERT INTO ruins (id, name, civilization, difficulty, description, image, min_level, estimated_time, potential_relics, event_pool, rewards) VALUES
('ruin-001-0000-0000-0000-000000000000', '吉萨金字塔群', 'egypt', 3, '位于尼罗河西岸的宏伟金字塔群，包括胡夫金字塔、哈夫拉金字塔和孟卡拉金字塔。古老的法老陵墓中隐藏着无数秘密和陷阱。', '🏜️', 1, 30, ARRAY['relic-001','relic-002','relic-003','relic-004'], ARRAY['event-001','event-002','event-003','event-006'], '{"goldMin": 100, "goldMax": 500, "exp": 50}'::jsonb),
('ruin-002-0000-0000-0000-000000000000', '蒂卡尔玛雅古城', 'maya', 4, '隐藏在危地马拉热带雨林深处的玛雅最大城市遗址。高耸的神庙和神秘的象形文字记载着这个失落文明的辉煌。', '🌴', 3, 45, ARRAY['relic-005','relic-006','relic-007','relic-008'], ARRAY['event-002','event-004','event-005','event-007'], '{"goldMin": 200, "goldMax": 800, "exp": 100}'::jsonb),
('ruin-003-0000-0000-0000-000000000000', '亚特兰蒂斯海底神殿', 'atlantis', 5, '传说中沉入大西洋深处的先进文明遗迹。水晶构成的神殿在深海中依然散发着神秘的光芒，但危险也无处不在。', '🌊', 5, 60, ARRAY['relic-009','relic-010','relic-011','relic-012'], ARRAY['event-001','event-003','event-005','event-008'], '{"goldMin": 500, "goldMax": 2000, "exp": 200}'::jsonb),
('ruin-004-0000-0000-0000-000000000000', '罗马斗兽场地下迷宫', 'rome', 3, '罗马斗兽场地下隐藏着复杂的通道和房间网络。这里曾是角斗士和猛兽的准备区，可能藏有罗马帝国时期的珍贵文物。', '⚔️', 2, 35, ARRAY['relic-013','relic-014','relic-015','relic-016'], ARRAY['event-002','event-006','event-009','event-010'], '{"goldMin": 150, "goldMax": 600, "exp": 75}'::jsonb),
('ruin-005-0000-0000-0000-000000000000', '秦始皇陵地宫', 'china', 5, '中国第一位皇帝的陵墓，传说中以水银为江河、以宝石为日月星辰。无数机关陷阱守护着这位千古一帝的安息之所。', '🏯', 6, 70, ARRAY['relic-017','relic-018','relic-019','relic-020'], ARRAY['event-001','event-004','event-007','event-011'], '{"goldMin": 600, "goldMax": 2500, "exp": 250}'::jsonb),
('ruin-006-0000-0000-0000-000000000000', '巴比伦空中花园遗址', 'mesopotamia', 4, '传说中的世界七大奇迹之一，由尼布甲尼撒二世为其王妃建造。虽然地面建筑已不复存在，但地下可能仍保存着珍贵的遗迹。', '🌺', 4, 50, ARRAY['relic-021','relic-022','relic-023','relic-024'], ARRAY['event-003','event-005','event-008','event-012'], '{"goldMin": 300, "goldMax": 1200, "exp": 150}'::jsonb);
INSERT INTO team_members (id, name, profession, skill_level, luck, rarity, avatar, skills, description, player_id, is_recruited) VALUES
('member-001-0000-0000-0000-000000000000', '林风', 'explorer', 5, 8, 'legendary', '🧭', '{"explorationSpeed": 95, "relicDiscovery": 88, "trapHandling": 90, "repairBonus": 60}'::jsonb, '身经百战的传奇探险家，曾独自穿越亚马逊雨林，发现三处未被记录的古代遗址。对各种地形都了如指掌。', NULL, true),
('member-002-0000-0000-0000-000000000000', '陈静怡', 'linguist', 5, 6, 'epic', '📜', '{"explorationSpeed": 50, "relicDiscovery": 92, "trapHandling": 40, "repairBonus": 85}'::jsonb, '精通八种古文字专家，曾成功破译过玛雅象形文字和埃及圣书体。能从模糊的刻文中读出被遗忘的历史。', NULL, true),
('member-003-0000-0000-0000-000000000000', '王铁柱', 'engineer', 4, 5, 'epic', '🔧', '{"explorationSpeed": 70, "relicDiscovery": 55, "trapHandling": 95, "repairBonus": 92}'::jsonb, '天才机械工程师，擅长破解古代机关和修复精密机械装置。任何陷阱在他眼中不过是精巧的谜题。', NULL, true),
('member-004-0000-0000-0000-000000000000', '苏雅', 'archaeologist', 5, 7, 'legendary', '🏺', '{"explorationSpeed": 60, "relicDiscovery": 98, "trapHandling": 65, "repairBonus": 90}'::jsonb, '天赋异禀的考古学天才，能凭直觉判断文物埋藏位置。经手发掘的文物数量超过许多老前辈一生的成就。', NULL, true),
('member-005-0000-0000-0000-000000000000', '周博文', 'historian', 4, 6, 'epic', '📚', '{"explorationSpeed": 45, "relicDiscovery": 85, "trapHandling": 50, "repairBonus": 95}'::jsonb, '博学的历史学教授，对六大文明的历史如数家珍。能从蛛丝马迹中还原历史真相。', NULL, true),
('member-006-0000-0000-0000-000000000000', '阿力', 'explorer', 3, 7, 'rare', '🏃', '{"explorationSpeed": 82, "relicDiscovery": 65, "trapHandling": 70, "repairBonus": 40}'::jsonb, '出身沙漠游牧民族后裔，对极端环境适应能力极强。嗅觉灵敏，能闻出地下水和矿藏的气味。', NULL, true),
('member-007-0000-0000-0000-000000000000', '林雪', 'linguist', 3, 5, 'rare', '✍️', '{"explorationSpeed": 40, "relicDiscovery": 78, "trapHandling": 35, "repairBonus": 72}'::jsonb, '年轻有为的语言学博士，专注于研究已灭绝的文字系统。记忆超群，过目不忘。', NULL, true),
('member-008-0000-0000-0000-000000000000', '张师傅', 'engineer', 3, 4, 'rare', '⚙️', '{"explorationSpeed": 55, "relicDiscovery": 45, "trapHandling": 85, "repairBonus": 80}'::jsonb, '退休的军工工程师，动手能力极强。什么东西到他手里都能拆了再装回去。', NULL, true),
('member-009-0000-0000-0000-000000000000', '方晓', 'archaeologist', 3, 6, 'rare', '🔍', '{"explorationSpeed": 50, "relicDiscovery": 88, "trapHandling": 55, "repairBonus": 75}'::jsonb, '田野考古经验丰富，擅长识别地层和文物断代。手上的老茧是多年发掘的勋章。', NULL, true),
('member-010-0000-0000-0000-000000000000', '赵老师', 'historian', 3, 5, 'rare', '🎓', '{"explorationSpeed": 38, "relicDiscovery": 72, "trapHandling": 40, "repairBonus": 78}'::jsonb, '历史系副教授，发表过多篇有影响力的论文。理论功底扎实，善于逻辑推理。', NULL, true),
('member-011-0000-0000-0000-000000000000', '小明', 'explorer', 2, 4, 'common', '🎒', '{"explorationSpeed": 60, "relicDiscovery": 45, "trapHandling": 50, "repairBonus": 25}'::jsonb, '刚入行的探险爱好者，充满激情但经验不足。总是冲在最前面，偶尔能歪打正着。', NULL, true),
('member-012-0000-0000-0000-000000000000', '小红', 'linguist', 2, 3, 'common', '📖', '{"explorationSpeed": 30, "relicDiscovery": 55, "trapHandling": 25, "repairBonus": 50}'::jsonb, '古文字学研究生，正在写毕业论文。能读懂简单的铭文，但复杂的还需要请教导师。', NULL, true),
('member-013-0000-0000-0000-000000000000', '小李', 'engineer', 2, 3, 'common', '🔨', '{"explorationSpeed": 40, "relicDiscovery": 30, "trapHandling": 65, "repairBonus": 55}'::jsonb, '机械工程专业的应届毕业生，理论知识丰富但实践不多。对古代机械充满好奇。', NULL, true),
('member-014-0000-0000-0000-000000000000', '小王', 'archaeologist', 2, 5, 'common', '🪣', '{"explorationSpeed": 35, "relicDiscovery": 65, "trapHandling": 35, "repairBonus": 50}'::jsonb, '考古系实习生，挖过几个小遗址。手很稳，发掘时小心翼翼从不弄坏东西。', NULL, true),
('member-015-0000-0000-0000-000000000000', '小刘', 'historian', 2, 4, 'common', '📝', '{"explorationSpeed": 28, "relicDiscovery": 50, "trapHandling": 30, "repairBonus": 52}'::jsonb, '历史爱好者，读过很多书但没什么实战经验。总能讲出有趣的历史小故事。', NULL, true),
('member-016-0000-0000-0000-000000000000', '马可', 'explorer', 4, 9, 'legendary', '🗺️', '{"explorationSpeed": 90, "relicDiscovery": 80, "trapHandling": 85, "repairBonus": 55}'::jsonb, '传说中的幸运儿，据说每次探险都能逢凶化吉。运气好到让人嫉妒。', NULL, true),
('member-017-0000-0000-0000-000000000000', '艾琳', 'archaeologist', 4, 6, 'epic', '🌿', '{"explorationSpeed": 55, "relicDiscovery": 90, "trapHandling": 60, "repairBonus": 88}'::jsonb, '来自英国的考古学家，擅长水下考古。曾参与过多次沉船打捞工作。', NULL, true),
('member-018-0000-0000-0000-000000000000', '哈桑', 'explorer', 3, 6, 'rare', '🐪', '{"explorationSpeed": 78, "relicDiscovery": 60, "trapHandling": 72, "repairBonus": 45}'::jsonb, '埃及本地人，从小在金字塔群附近长大。对沙漠地形了如指掌。', NULL, true),
('member-019-0000-0000-0000-000000000000', '娜塔莎', 'linguist', 4, 5, 'epic', '🔮', '{"explorationSpeed": 48, "relicDiscovery": 88, "trapHandling": 45, "repairBonus": 82}'::jsonb, '俄罗斯语言学家，精通12种语言，包括多种已消亡的古文字。', NULL, true),
('member-020-0000-0000-0000-000000000000', '老王', 'engineer', 5, 6, 'legendary', '🛠️', '{"explorationSpeed": 65, "relicDiscovery": 60, "trapHandling": 98, "repairBonus": 95}'::jsonb, '国宝级文物修复大师，参与过多个国家级文物修复项目。', NULL, true),
('member-021-0000-0000-0000-000000000000', '艾米丽', 'historian', 3, 5, 'rare', '🕯️', '{"explorationSpeed": 42, "relicDiscovery": 75, "trapHandling": 48, "repairBonus": 80}'::jsonb, '专攻罗马史的青年学者，对罗马帝国的军事制度有深入研究。', NULL, true),
('member-022-0000-0000-0000-000000000000', '大壮', 'explorer', 2, 5, 'common', '💪', '{"explorationSpeed": 55, "relicDiscovery": 40, "trapHandling": 55, "repairBonus": 30}'::jsonb, '健身教练转行的探险队员，体力过人，能搬动重物。', NULL, true),
('member-023-0000-0000-0000-000000000000', '小雅', 'archaeologist', 4, 8, 'epic', '🌸', '{"explorationSpeed": 52, "relicDiscovery": 92, "trapHandling": 58, "repairBonus": 85}'::jsonb, '年轻有为的考古学博士，曾发现过多个重要的新石器时代遗址。', NULL, true),
('member-024-0000-0000-0000-000000000000', '托尼', 'engineer', 3, 4, 'rare', '🔩', '{"explorationSpeed": 58, "relicDiscovery": 48, "trapHandling": 82, "repairBonus": 78}'::jsonb, '德国机械工程师，做事严谨仔细，从不放过任何细节。', NULL, true),
('member-025-0000-0000-0000-000000000000', '美咲', 'linguist', 2, 4, 'common', '🎎', '{"explorationSpeed": 35, "relicDiscovery": 58, "trapHandling": 30, "repairBonus": 55}'::jsonb, '日本留学生，对东亚古代文字系统有浓厚兴趣。', NULL, true),
('member-026-0000-0000-0000-000000000000', '卡洛斯', 'explorer', 3, 7, 'rare', '🌵', '{"explorationSpeed": 80, "relicDiscovery": 62, "trapHandling": 68, "repairBonus": 38}'::jsonb, '墨西哥裔探险家，从小在玛雅遗址附近长大，熟悉热带雨林环境。', NULL, true),
('member-027-0000-0000-0000-000000000000', '沈教授', 'historian', 5, 6, 'legendary', '🎩', '{"explorationSpeed": 40, "relicDiscovery": 90, "trapHandling": 55, "repairBonus": 98}'::jsonb, '著名秦汉史专家，被誉为秦俑研究第一人。', NULL, true),
('member-028-0000-0000-0000-000000000000', '苏菲', 'archaeologist', 2, 4, 'common', '🌻', '{"explorationSpeed": 38, "relicDiscovery": 60, "trapHandling": 38, "repairBonus": 52}'::jsonb, '考古系研究生二年级，对美索不达米亚文明充满热情。', NULL, true),
('member-029-0000-0000-0000-000000000000', '老陈', 'engineer', 2, 4, 'common', '🧰', '{"explorationSpeed": 42, "relicDiscovery": 35, "trapHandling": 60, "repairBonus": 58}'::jsonb, '退休的建筑工人，动手能力强，什么都能修。', NULL, true),
('member-030-0000-0000-0000-000000000000', '珍妮', 'historian', 4, 7, 'epic', '📖', '{"explorationSpeed": 44, "relicDiscovery": 82, "trapHandling": 52, "repairBonus": 88}'::jsonb, '研究亚特兰蒂斯传说的权威学者，坚信这个文明真实存在。', NULL, true);
INSERT INTO relics (id, name, civilization, completeness, rarity, historical_value, estimated_price, description, image, fragments, discovered_at, repair_history, in_museum, on_market, player_id) VALUES
('relic-001-0000-0000-0000-000000000000', '圣甲虫护身符', 'egypt', 95, 'common', 800, 1200, '古埃及常见的护身符，圣甲虫形象象征重生与永恒。背面刻有简单的象形文字，据说是工匠墓中的陪葬品。', '🪲', 1, NOW(), '[]'::jsonb, false, false, NULL),
('relic-002-0000-0000-0000-000000000000', '法老黄金面具碎片', 'egypt', 60, 'epic', 25000, 35000, '从某具不明法老木乃伊面具的黄金碎片，虽然残缺，但含金量极高，上面还残留着青金石和红玉镶嵌。', '👑', 3, NOW(), '[]'::jsonb, false, false, NULL),
('relic-003-0000-0000-0000-000000000000', '《亡灵书》莎草纸', 'egypt', 75, 'rare', 8000, 12000, '一份保存尚好的莎草纸卷，上面用僧侣体文字抄写着帮助亡者通往来世的咒语和神话。', '📜', 2, NOW(), '[]'::jsonb, false, false, NULL),
('relic-004-0000-0000-0000-000000000000', '图坦卡蒙匕首', 'egypt', 98, 'legendary', 150000, 200000, '传说中的陨铁匕首，刀身由陨石打造，历经数千年仍然寒光闪闪。刀柄上刻有精美花纹。', '🗡️', 1, NOW(), '[]'::jsonb, false, false, NULL),
('relic-005-0000-0000-0000-000000000000', '玛雅太阳历石碑', 'maya', 85, 'rare', 12000, 18000, '刻有玛雅长历法的石碑残片，记载着一个重要的天文观测记录。', '📅', 2, NOW(), '[]'::jsonb, false, false, NULL),
('relic-006-0000-0000-0000-000000000000', '翡翠面具', 'maya', 70, 'epic', 30000, 45000, '由数百块翡翠拼接而成的祭祀面具，曾用于重要的宗教仪式。眼眶处镶嵌有贝壳和黑曜石。', '🎭', 4, NOW(), '[]'::jsonb, false, false, NULL),
('relic-007-0000-0000-0000-000000000000', '可可豆陶碗', 'maya', 90, 'common', 600, 900, '绘制着简单花纹的陶碗，内壁还残留着古代可可饮品的痕迹。可可在玛雅文化中具有神圣意义。', '🥣', 1, NOW(), '[]'::jsonb, false, false, NULL),
('relic-008-0000-0000-0000-000000000000', '水晶头颅', 'maya', 100, 'legendary', 200000, 280000, '由纯净水晶雕刻的完美头颅，工艺之精湛令人难以置信。传说拥有神秘的预言力量。', '💀', 1, NOW(), '[]'::jsonb, false, false, NULL),
('relic-009-0000-0000-0000-000000000000', '亚特兰蒂斯能量水晶', 'atlantis', 88, 'epic', 40000, 60000, '一块切割完美的蓝色水晶，在黑暗中会发出微弱的荧光。据说这是亚特兰蒂斯能源系统的核心部件。', '💎', 2, NOW(), '[]'::jsonb, false, false, NULL),
('relic-010-0000-0000-0000-000000000000', '海神三叉戟', 'atlantis', 55, 'legendary', 300000, 400000, '传说中海王波塞冬使用过的三叉戟残件。虽然只剩下戟头和部分戟杆，但仍能感受到其中蕴含的力量。', '🔱', 5, NOW(), '[]'::jsonb, false, false, NULL),
('relic-011-0000-0000-0000-000000000000', '海底陶罐', 'atlantis', 80, 'common', 1500, 2200, '在海底泥沙中保存完好的陶罐，材质特殊，表面的釉料似乎能防水。', '🏺', 1, NOW(), '[]'::jsonb, false, false, NULL),
('relic-012-0000-0000-0000-000000000000', '亚特兰蒂斯星图盘', 'atlantis', 72, 'rare', 15000, 22000, '青铜制星图盘，上面标注着星辰的位置，据说是亚特兰蒂斯人用于航海导航的工具。', '🧭', 3, NOW(), '[]'::jsonb, false, false, NULL),
('relic-013-0000-0000-0000-000000000000', '罗马军团鹰旗', 'rome', 40, 'rare', 9000, 14000, '罗马军团的鹰旗残片，虽然布料已经腐朽不堪，但金鹰的形象依然清晰可辨。这是罗马军团荣誉的象征。', '🦅', 4, NOW(), '[]'::jsonb, false, false, NULL),
('relic-014-0000-0000-0000-000000000000', '角斗士头盔', 'rome', 65, 'common', 2000, 3000, '角斗士使用过的青铜头盔，上面有打斗留下的凹痕。面罩已经变形。', '⛑️', 2, NOW(), '[]'::jsonb, false, false, NULL),
('relic-015-0000-0000-0000-000000000000', '奥古斯都金币', 'rome', 99, 'epic', 22000, 32000, '罗马帝国开国皇帝奥古斯都时期的金币，铸造精美，保存完好。正面是奥古斯都头像，背面是象征和平女神。', '🪙', 1, NOW(), '[]'::jsonb, false, false, NULL),
('relic-016-0000-0000-0000-000000000000', '凯撒佩剑', 'rome', 50, 'legendary', 180000, 250000, '据说属于尤利乌斯·凯撒本人使用过的佩剑，剑柄镶嵌着宝石。虽然剑身已锈迹斑斑，但威严犹在。', '⚔️', 3, NOW(), '[]'::jsonb, false, false, NULL),
('relic-017-0000-0000-0000-000000000000', '兵马俑将军俑', 'china', 85, 'epic', 35000, 50000, '秦始皇陵中的高级军吏俑，神态威严，盔甲纹饰精细。身上还残留着彩绘的痕迹。', '🗿', 2, NOW(), '[]'::jsonb, false, false, NULL),
('relic-018-0000-0000-0000-000000000000', '青铜剑', 'china', 92, 'rare', 10000, 15000, '战国时期的青铜剑，铸造工艺精湛，历经两千余年依然锋利无比。剑身上有精美花纹。', '🗡️', 1, NOW(), '[]'::jsonb, false, false, NULL),
('relic-019-0000-0000-0000-000000000000', '玉璧', 'china', 96, 'common', 3500, 5000, '汉代玉璧，质地温润，雕刻着简单的谷纹。玉璧在中国古代象征着天圆地方的宇宙观。', '⭕', 1, NOW(), '[]'::jsonb, false, false, NULL),
('relic-020-0000-0000-0000-000000000000', '传国玉玺', 'china', 45, 'legendary', 500000, 700000, '传说中用和氏璧雕琢而成的传国玉玺的残片。上面"受命于天，既寿永昌"八个字依稀可辨。', '📦', 6, NOW(), '[]'::jsonb, false, false, NULL),
('relic-021-0000-0000-0000-000000000000', '楔形文字泥板', 'mesopotamia', 78, 'rare', 7000, 11000, '刻有楔形文字的泥板，记录着一份古代商队的贸易记录。这是人类最早的文字记录之一。', '📋', 2, NOW(), '[]'::jsonb, false, false, NULL),
('relic-022-0000-0000-0000-000000000000', '汉谟拉比法典石碑', 'mesopotamia', 55, 'epic', 28000, 42000, '世界上最早的成文法典石碑残片，上面刻有古巴比伦王国的法律条文。', '⚖️', 4, NOW(), '[]'::jsonb, false, false, NULL),
('relic-023-0000-0000-0000-000000000000', '黄金公牛雕像', 'mesopotamia', 88, 'common', 1800, 2700, '小型黄金公牛雕像，是美索不达米亚地区常见的祭祀用品，象征着力量与丰饶。', '🐂', 1, NOW(), '[]'::jsonb, false, false, NULL),
('relic-024-0000-0000-0000-000000000000', '吉尔伽美什石板', 'mesopotamia', 68, 'legendary', 250000, 350000, '《吉尔伽美什史诗》的原始石板残片，上面记载着人类最古老的英雄史诗。', '📖', 5, NOW(), '[]'::jsonb, false, false, NULL);
